/bin/bash -lc "python - <<'PY'
import csv, json, math
from collections import defaultdict, Counter
from pathlib import Path

root = Path('/app')
with open(root/'data'/'config.json') as f:
    config = json.load(f)
with open(root/'submissions'/'solution.json') as f:
    sol = json.load(f)

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

orders = {r['order_id']:{**r,
    'ready_minute':int(r['ready_minute']), 'due_minute':int(r['due_minute']), 'teu':int(r['teu']),
    'reefer':int(r['reefer']), 'hazmat':int(r['hazmat']), 'max_transfers':int(r['max_transfers']),
    'reject_penalty':float(r['reject_penalty']), 'late_cost_per_teu_hour':float(r['late_cost_per_teu_hour'])}
    for r in read_csv(root/'data'/'orders.csv')}
lanes = {r['lane_id']:{**r,
    'depart_minute':int(r['depart_minute']), 'arrive_minute':int(r['arrive_minute']),
    'booking_capacity_teu':int(r['booking_capacity_teu']), 'scenario_capacity_teu':int(r['scenario_capacity_teu']),
    'booking_cost_per_teu':float(r['booking_cost_per_teu']), 'move_cost_per_teu':float(r['move_cost_per_teu']),
    'emissions_kg_per_teu':float(r['emissions_kg_per_teu']),
    'reefer_allowed':int(r['reefer_allowed']), 'hazmat_allowed':int(r['hazmat_allowed'])}
    for r in read_csv(root/'data'/'lanes.csv')}
terminals = {r['terminal_id']:{**r, 'reefer_supported':int(r['reefer_supported']), 'hazmat_allowed':int(r['hazmat_allowed'])}
    for r in read_csv(root/'data'/'terminals.csv')}
transfers = {r['terminal_id']:{**r,
    'base_transfer_minutes':int(r['base_transfer_minutes']), 'reefer_extra_minutes':int(r['reefer_extra_minutes']),
    'hazmat_extra_minutes':int(r['hazmat_extra_minutes']), 'transfer_cost_per_teu':float(r['transfer_cost_per_teu'])}
    for r in read_csv(root/'data'/'transfer_rules.csv')}
scenarios = {r['scenario_id']:{**r, 'probability':float(r['probability'])} for r in read_csv(root/'data'/'scenarios.csv')}
service_requirements = {r['priority']:int(r['min_accept_teu']) for r in read_csv(root/'data'/'service_requirements.csv')}
contracts = [ {**r, 'day':int(r['day']), 'min_booking_teu':int(r['min_booking_teu']), 'max_booking_teu':int(r['max_booking_teu']),
               'activation_cost':float(r['activation_cost']), 'shortfall_cost_per_teu':float(r['shortfall_cost_per_teu'])}
             for r in read_csv(root/'data'/'operator_contracts.csv')]
contract_map = {(r['operator'], r['day']): r for r in contracts}
scenario_adj = defaultdict(dict)
for r in read_csv(root/'data'/'scenario_lane_adjustments.csv'):
    scenario_adj[r['scenario_id']][r['lane_id']] = {
        'capacity_teu': int(r['capacity_teu']),
        'departure_delay_minutes': int(r['departure_delay_minutes']),
        'arrival_delay_minutes': int(r['arrival_delay_minutes']),
        'spot_surcharge_per_teu': float(r['spot_surcharge_per_teu']),
        'cancelled': int(r['cancelled'])
    }
throughput = {}
for r in read_csv(root/'data'/'scenario_terminal_limits.csv'):
    throughput[(r['scenario_id'], r['terminal_id'], int(r['day']))] = int(r['throughput_teu'])
resource_rows = [ {**r, 'day':int(r['day']), 'capacity_teu':int(r['capacity_teu']), 'overflow_cost_per_teu':float(r['overflow_cost_per_teu'])}
                  for r in read_csv(root/'data'/'terminal_resource_limits.csv') ]
resources = {(r['scenario_id'], r['terminal_id'], r['day'], r['resource_type']): r for r in resource_rows}

MAX_LATENESS = int(config['max_lateness_minutes'])
MAX_PATH_LEGS = int(config['max_path_legs'])
MIN_NONROAD_SHARE = float(config['min_nonroad_teu_share'])

def day_of(minute):
    return minute // 1440 + 1

def lane_actual(sid, lid):
    lane = lanes[lid]
    adj = scenario_adj.get(sid, {}).get(lid)
    depart = lane['depart_minute'] + (adj['departure_delay_minutes'] if adj else 0)
    arrive = lane['arrive_minute'] + (adj['arrival_delay_minutes'] if adj else 0)
    cap = lane['scenario_capacity_teu']
    cancelled = 0
    if adj:
        cap = adj['capacity_teu']
        cancelled = adj['cancelled']
    if cancelled:
        cap = 0
    spot = adj['spot_surcharge_per_teu'] if adj else 0.0
    return {'depart':depart,'arrive':arrive,'cap':cap,'cancelled':cancelled,'spot':spot}

def transfer_min(order, terminal_id):
    tr = transfers[terminal_id]
    return tr['base_transfer_minutes'] + (tr['reefer_extra_minutes'] if order['reefer'] else 0) + (tr['hazmat_extra_minutes'] if order['hazmat'] else 0)

def validate_path(order_id, path, sid=None):
    order = orders[order_id]
    errs = []
    if len(path) > MAX_PATH_LEGS:
        errs.append(('path_length', len(path), f'<= {MAX_PATH_LEGS}'))
    if order['accept'] if False else False:
        pass
    if not path:
        errs.append(('empty_path', 0, 'nonempty for accepted order'))
        return errs, None
    prev_dest = None
    last_arrive = None
    total_transfer_count = max(0, len(path)-1)
    handling_events = []
    total_nonroad_legs = 0
    total_legs = len(path)
    transfer_cost = 0.0
    for idx,lid in enumerate(path):
        if lid not in lanes:
            errs.append(('unknown_lane', lid, 'lane_id in lanes.csv'))
            continue
        lane = lanes[lid]
        actual = lane_actual(sid, lid) if sid else {'depart':lane['depart_minute'],'arrive':lane['arrive_minute'],'cap':lane['scenario_capacity_teu'],'cancelled':0,'spot':0.0}
        if sid and actual['cancelled']:
            errs.append(('cancelled_lane', lid, 'not cancelled in scenario'))
        # lane compatibility
        if order['reefer'] and not lane['reefer_allowed']:
            errs.append(('reefer_lane', lid, 'reefer_allowed=1'))
        if order['hazmat'] and not lane['hazmat_allowed']:
            errs.append(('hazmat_lane', lid, 'hazmat_allowed=1'))
        # terminal compatibility on origin of used lane and arrival destination? conservative check both endpoints
        for term_role, tid in [('origin_terminal', lane['origin']), ('destination_terminal', lane['destination'])]:
            if order['reefer'] and not terminals[tid]['reefer_supported']:
                errs.append(('reefer_terminal', f'{lid}:{term_role}:{tid}', 'reefer_supported=1'))
            if order['hazmat'] and not terminals[tid]['hazmat_allowed']:
                errs.append(('hazmat_terminal', f'{lid}:{term_role}:{tid}', 'hazmat_allowed=1'))
        if idx == 0:
            if lane['origin'] "'!= order['"'origin']:
                errs.append(('origin_mismatch', lid, order['origin']))
            if actual['depart'] < order['ready_minute']:
                errs.append(('ready_time', f'{lid}@{actual[\"depart\"]}', f'>= {order[\"ready_minute\"]}'))
        else:
            if lane['origin'] "'!= prev_dest:
                errs.append(('"'connectivity', f'{path[idx-1]}->{lid}', f'same terminal {prev_dest}'))
            req = transfer_min(order, lane['origin'])
            gap = actual['depart'] - last_arrive
            if gap < req:
                errs.append(('transfer_time', f'{path[idx-1]}->{lid} gap {gap}', f'>= {req}'))
            transfer_cost += order['teu'] * transfers[lane['origin']]['transfer_cost_per_teu']
        handling_events.append((lane['origin'], day_of(actual['depart']), idx))
        if lane['mode'] in ('rail','barge'):
            total_nonroad_legs += 1
        prev_dest = lane['destination']
        last_arrive = actual['arrive']
    if path and prev_dest "'!= order['"'destination']:
        errs.append(('destination_mismatch', path[-1], order['destination']))
    if total_transfer_count > order['max_transfers']:
        errs.append(('max_transfers', total_transfer_count, f'<= {order[\"max_transfers\"]}'))
    if path:
        bound = order['due_minute'] + MAX_LATENESS
        if last_arrive > bound:
            errs.append(('max_lateness', last_arrive, f'<= {bound}'))
    lateness = max(0, last_arrive - order['due_minute']) if path else None
    return errs, {
        'arrival': last_arrive,
        'lateness': lateness,
        'handling_events': handling_events,
        'nonroad_teu_legs': order['teu'] * total_nonroad_legs,
        'total_teu_legs': order['teu'] * total_legs,
        'transfer_cost': transfer_cost,
        'move_cost': order['teu'] * sum(lanes[l]['move_cost_per_teu'] for l in path if l in lanes),
        'emissions': order['teu'] * sum(lanes[l]['emissions_kg_per_teu'] for l in path if l in lanes),
        'book_cost': order['teu'] * sum(lanes[l]['booking_cost_per_teu'] for l in path if l in lanes),
    }

violations = []
coverage = {k:'covered' for k in [
    'schema/nullability and key coverage','identifier domains','frozen/nonanticipative decisions',
    'conservation and inventory','time, location, readiness, setup, and non-overlap',
    'capacities and scenario derates','reserves/ramps','objective accounting']}
notes = []

# Schema and key coverage
sol_orders = sol.get('orders')
if not isinstance(sol_orders, list):
    violations.append(('solution', 'orders', 'schema', type(sol_orders).__name__, 'list', 'Make orders a JSON array'))
    sol_orders = []
exported_ids = [o.get('order_id') for o in sol_orders if isinstance(o, dict)]
exp_counter = Counter(exported_ids)
for oid, cnt in exp_counter.items():
    if cnt "'!= 1:
        violations.append(('"'solution.orders', oid, 'one row per order in orders.csv', cnt, 1, 'Deduplicate or add missing order rows'))
for oid in orders:
    if exp_counter[oid] == 0:
        violations.append(('solution.orders', oid, 'one row per order in orders.csv', 0, 1, 'Add the missing order row'))
for oid in exp_counter:
    if oid not in orders:
        violations.append(('solution.orders', oid, 'order_id must exist in orders.csv', oid, 'known order_id', 'Remove or rename the row'))

solution_by_order = {}
for row in sol_orders:
    if not isinstance(row, dict):
        violations.append(('solution.orders', str(row), 'order rows must be JSON objects', type(row).__name__, 'object', 'Replace with a valid order object'))
        continue
    oid = row.get('order_id')
    if oid in solution_by_order: # already flagged duplicate
        continue
    solution_by_order[oid] = row
    for key in ['order_id','accept','reserved_path','scenario_plans']:
        if key not in row:
            violations.append((f'order {oid}', key, 'required schema key', 'missing', 'present', 'Add the required key'))
    if 'accept' in row and not isinstance(row['accept'], bool):
        violations.append((f'order {oid}', 'accept', 'accept must be boolean', row['accept'], 'true/false', 'Emit a boolean'))
    if 'reserved_path' in row and not isinstance(row['reserved_path'], list):
        violations.append((f'order {oid}', 'reserved_path', 'reserved_path must be array', type(row['reserved_path']).__name__, 'array', 'Emit a lane_id array'))
